"""Validate a Release Transparency Tracker CSV.

Usage: python validate.py data.csv
"""
import csv
import sys
from datetime import date

REQUIRED = [
    "developer", "model", "release_date", "system_card", "system_card_date",
    "dangerous_capability_evals_published", "third_party_predeployment_testing",
    "framework_referenced", "source_urls", "accessed_date", "checked_by", "notes",
]
TRISTATE = {"yes", "no", "partial", "unknown"}
TRISTATE_FIELDS = [
    "system_card", "dangerous_capability_evals_published",
    "third_party_predeployment_testing", "framework_referenced",
]


def parse_date(s):
    try:
        return date.fromisoformat(s)
    except ValueError:
        return None


def validate(path):
    errors = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        missing = [c for c in REQUIRED if c not in (reader.fieldnames or [])]
        if missing:
            return [f"missing columns: {missing}"]
        for i, row in enumerate(reader, start=2):
            where = f"row {i} ({row['developer']} {row['model']})"
            if not parse_date(row["release_date"]):
                errors.append(f"{where}: bad release_date")
            if not parse_date(row["accessed_date"]):
                errors.append(f"{where}: bad accessed_date")
            for fld in TRISTATE_FIELDS:
                if row[fld].strip().lower() not in TRISTATE:
                    errors.append(f"{where}: {fld} must be one of {sorted(TRISTATE)}")
            if row["system_card_date"] and row["system_card_date"] != "unknown":
                if not parse_date(row["system_card_date"]):
                    errors.append(f"{where}: bad system_card_date")
            if not row["source_urls"].strip():
                errors.append(f"{where}: no sources")
            if not row["checked_by"].strip():
                errors.append(f"{where}: not second-checked")
    return errors


def lag_days(row):
    """Days from release to system card (negative = published before release)."""
    r, s = parse_date(row["release_date"]), parse_date(row["system_card_date"] or "")
    return (s - r).days if r and s else None


if __name__ == "__main__":
    errs = validate(sys.argv[1])
    print("\n".join(errs) if errs else "OK")
    sys.exit(1 if errs else 0)
